.toast b { color: var(--gold); }
@keyframes fade { 0%,85% { opacity: 1 } 100% { opacity: 0 } }

/* 底部头像栏 */
.cast { position: absolute; left: 50%; bottom: 10px; transform: translateX(-50%); display: flex; gap: 8px; padding: 8px; }
